async function loadAdminWarehouses(){if(!warehouseList)return;let rows=await api('/api/admin/warehouses');warehouseList.textContent='';rows.forEach(w=>{let row=document.createElement('div');row.className='row warehouse-row';let info=document.createElement('div'),name=document.createElement('strong'),meta=document.createElement('small');name.textContent=w.name;let occupancy='Vazio';if(!w.empty){let parts=[];if(w.nonzero_items)parts.push(w.nonzero_items+' item'+(w.nonzero_items===1?'':'s')+' com saldo');if(w.asset_count)parts.push(w.asset_count+' patrimônio'+(w.asset_count===1?'':'s'));occupancy=parts.join(' · ')}meta.textContent=(w.active?'Ativo':'Inativo')+' · '+occupancy;info.append(name,meta);let action=document.createElement('button');action.type='button';action.className='secondary';action.textContent=w.active?'Desativar':'Ativar';action.addEventListener('click',async()=>{action.disabled=true;setFeedback(warehouseStatus,'loading',w.active?'Validando ocupação e desativando…':'Ativando depósito…');try{await api('/api/admin/warehouses/'+w.id+'/'+(w.active?'deactivate':'activate'),{method:'POST',body:'{}'});setFeedback(warehouseStatus,'success',w.active?w.name+' desativado.':w.name+' ativado.');await loadAdminWarehouses()}catch(err){setFeedback(warehouseStatus,'error',uiErrorMessage(err,'Não foi possível alterar '+w.name+'.'))}finally{action.disabled=false}});row.append(info,action);warehouseList.append(row)})}
