let profileForm=document.getElementById('adminProfileForm'),profiles=[],perms=[],selectedProfile=0,permSelection=document.getElementById('adminPermSelection'),permSave=document.getElementById('adminSavePerms'),permStatus=document.getElementById('adminPermStatus');
