if(createTotal)createTotal.addEventListener('submit',async e=>{e.preventDefault();let submit=e.submitter||createTotal.querySelector('button[type="submit"]');if(submit?.dataset.busy==='1')return;let pending=readInventoryCreatePending();if(pending&&pending.type!=='TOTAL'){applyInventoryCreatePending();return}if(!pending&&!requireFields(createTotal,listMsg))return;let warehouseId=pending?+pending.warehouse_id:Number(createWarehouse.value);if(!warehouseId){setListMessage('Selecione um depósito.','error');return}if(!pending){pending={type:'TOTAL',operation_id:crypto.randomUUID(),warehouse_id:warehouseId};if(!await saveInventoryCreatePending(pending)){applyInventoryCreatePending();return}applyInventoryCreatePending()}await runLocked(submit,async()=>{setCreateMessage('Criando inventário total…');try{let out=await api('/api/inventory-validations/total',{method:'POST',body:JSON.stringify({operation_id:pending.operation_id,warehouse_id:pending.warehouse_id})});await clearInventoryCreatePending();applyInventoryCreatePending();setCreateMessage('Inventário total criado.','ok');listOffset=0;await loadList();await load(out.id)}catch(err){if(definitiveWriteError(err)){await clearInventoryCreatePending();applyInventoryCreatePending()}else applyInventoryCreatePending();setCreateMessage(uiErrorMessage(err,'Não foi possível confirmar a criação do inventário total. Reenvie a mesma tentativa.'),'error')}})});
if(createBlind)createBlind.addEventListener('submit',async e=>{e.preventDefault();let submit=e.submitter||createBlind.querySelector('button[type="submit"]');if(submit?.dataset.busy==='1')return;let pending=readInventoryCreatePending();if(pending&&pending.type!=='BLIND'){applyInventoryCreatePending();return}if(!pending){pending={type:'BLIND',operation_id:crypto.randomUUID()};if(!await saveInventoryCreatePending(pending)){applyInventoryCreatePending();return}applyInventoryCreatePending()}await runLocked(submit,async()=>{setCreateMessage('Criando inventário cego…');try{let out=await api('/api/inventory-validations/blind',{method:'POST',body:JSON.stringify({operation_id:pending.operation_id})});await clearInventoryCreatePending();applyInventoryCreatePending();setCreateMessage('Inventário cego criado.','ok');listOffset=0;await loadList();await load(out.id)}catch(err){if(definitiveWriteError(err)){await clearInventoryCreatePending();applyInventoryCreatePending()}else applyInventoryCreatePending();setCreateMessage(uiErrorMessage(err,'Não foi possível confirmar a criação do inventário cego. Reenvie a mesma tentativa.'),'error')}})});
openForm.addEventListener('submit',e=>{e.preventDefault();let id=Number(idInput.value);if(id>0)load(id)});
search.addEventListener('input',render);
