async function initReports(){
let form=document.getElementById('reportForm');if(!form)return;
let exportRows=[],exportType='';
let start=document.getElementById('reportStart'),end=document.getElementById('reportEnd'),startLabel=document.getElementById('reportStartLabel'),endLabel=document.getElementById('reportEndLabel'),endLabelText=document.getElementById('reportEndLabelText'),type=document.getElementById('reportType'),wh=document.getElementById('warehouse'),status=document.getElementById('reportStatus'),result=document.getElementById('reportResult'),head=document.getElementById('reportHead'),body=document.getElementById('reportBody'),title=document.getElementById('reportTitle'),meta=document.getElementById('reportMeta'),csvBtn=document.getElementById('reportCSV'),printBtn=document.getElementById('reportPrint');
try{await loadWarehouses(true,'/api/reports/warehouses')}catch(err){setFeedback(status,'error',uiErrorMessage(err,'Não foi possível carregar os depósitos do relatório.'));return}
function localDate(d){let y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return y+'-'+m+'-'+day}
function clearResult(){result.hidden=true;body.textContent='';exportRows=[];exportType='';csvBtn.disabled=true;printBtn.disabled=true;setFeedback(status,'','')}
function markPeriod(kind){document.querySelectorAll('[data-period]').forEach(x=>x.setAttribute('aria-pressed',x.dataset.period===kind?'true':'false'))}
function syncCustomDates(){let custom=document.querySelector('[data-period="custom"]')?.getAttribute('aria-pressed')==='true';startLabel.hidden=!custom||type.value==='SALDO';endLabel.hidden=!custom}
function setPeriod(kind){let now=new Date(),a=new Date(now.getFullYear(),now.getMonth(),now.getDate()),b=new Date(a);if(kind==='week'){a.setDate(a.getDate()-a.getDay())}else if(kind==='month'){a=new Date(now.getFullYear(),now.getMonth(),1)}start.value=localDate(a);end.value=localDate(b);markPeriod(kind);syncCustomDates();clearResult()}
function setCustomPeriod(){markPeriod('custom');syncCustomDates();clearResult();(type.value==='SALDO'?end:start).focus()}
function syncReportType(){let balance=type.value==='SALDO';start.required=!balance;endLabelText.textContent=balance?'Data de corte':'Até';document.querySelector('[data-period="week"]').hidden=balance;document.querySelector('[data-period="month"]').hidden=balance;if(balance)markPeriod(end.value===localDate(new Date())?'today':'custom');syncCustomDates()}
document.querySelectorAll('[data-period]').forEach(b=>{b.setAttribute('aria-pressed','false');b.onclick=()=>b.dataset.period==='custom'?setCustomPeriod():setPeriod(b.dataset.period)});[start,end].forEach(x=>x.addEventListener('change',()=>{markPeriod('custom');clearResult()}));type.addEventListener('change',()=>{syncReportType();clearResult()});wh.addEventListener('change',clearResult);setPeriod('today');syncReportType();
function bounds(){let a=new Date(start.value+'T00:00:00'),b=new Date(end.value+'T00:00:00');b.setDate(b.getDate()+1);return {start:a.toISOString(),end:b.toISOString()}}
function cell(tr,text){let td=document.createElement('td');td.textContent=text;tr.append(td)}
function header(labels){head.textContent='';let tr=document.createElement('tr');labels.forEach(x=>{let th=document.createElement('th');th.scope='col';th.textContent=x;tr.append(th)});head.append(tr)}
function money(v){let n=Number(v);return Number.isFinite(n)?new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n):v}
form.onsubmit=async e=>{e.preventDefault();if(!requireFields(form,status,'Informe o período do relatório.'))return;if(type.value!=='SALDO'&&start.value>end.value){setFeedback(status,'error','A data inicial não pode ser posterior à data final.');return}setFeedback(status,'loading','Gerando relatório…');result.hidden=true;body.textContent='';let p=bounds(),qs=new URLSearchParams();if(wh.value)qs.set('warehouse_id',wh.value);let rows;
try{if(type.value==='SALDO'){qs.set('before',p.end);rows=await api('/api/reports/balance?'+qs)}else{qs.set('type',type.value);qs.set('start',p.start);qs.set('end',p.end);rows=await api('/api/reports/movements?'+qs)}}catch(err){setFeedback(status,'error',uiErrorMessage(err,'Não foi possível gerar o relatório.'));return}
setFeedback(status,'','');result.hidden=false;exportRows=rows;exportType=type.value;csvBtn.disabled=!rows.length;printBtn.disabled=!rows.length;let label=type.options[type.selectedIndex].text;title.textContent=label;meta.textContent=type.value==='SALDO'?'Data de corte: '+end.value:(start.value===end.value?'Data: '+start.value:'Período: '+start.value+' a '+end.value);
if(type.value==='SALDO'){header(['Produto','Depósito','Saldo','Preço médio']);rows.forEach(r=>{let tr=document.createElement('tr');cell(tr,r.item+(r.brand?' - '+r.brand:''));cell(tr,r.warehouse);cell(tr,displayDecimal(r.quantity)+' '+r.unit);cell(tr,money(r.avg_cost));body.append(tr)})}else{header(['Data','Produto / SKU','Depósito','Quantidade','Custo unitário','Documento / fornecedor']);rows.forEach(r=>{let tr=document.createElement('tr');cell(tr,new Date(r.occurred_at).toLocaleString('pt-BR'));cell(tr,r.item+(r.sku?' · '+r.sku:''));cell(tr,r.warehouse);cell(tr,displayDecimal(r.quantity)+' '+r.unit);cell(tr,money(r.unit_cost));cell(tr,[r.document_number,r.supplier_name].filter(Boolean).join(' · '));body.append(tr)})}
if(!rows.length){let tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=type.value==='SALDO'?4:6;td.textContent='Nenhum registro encontrado para os filtros selecionados.';tr.append(td);body.append(tr)}
scrollToContext(result)}
function csvValue(v){let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function csvText(v){let s=String(v??'');return s&&/^\d+$/.test(s)?'\t'+s:s}
function exportCSV(){if(!exportRows.length)return;let headers,lines;if(exportType==='SALDO'){headers=['Produto','Depósito','Saldo','Unidade','Preço médio'];lines=exportRows.map(r=>[r.item+(r.brand?' - '+r.brand:''),r.warehouse,r.quantity,r.unit,r.avg_cost])}else{headers=['Data','Tipo','Produto','SKU','Código de barras','Depósito','Quantidade','Unidade','Custo unitário','Documento','Fornecedor','Responsável'];lines=exportRows.map(r=>[new Date(r.occurred_at).toLocaleString('pt-BR'),r.type,r.item,r.sku,csvText(r.barcode),r.warehouse,r.quantity,r.unit,r.unit_cost,r.document_number,r.supplier_name,r.responsible])}let csv='\uFEFF'+[headers,...lines].map(row=>row.map(csvValue).join(';')).join('\r\n'),blob=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=exportType==='SALDO'?'relatorio-saldo-ate-'+end.value+'.csv':'relatorio-'+exportType.toLowerCase()+'-'+start.value+'-a-'+end.value+'.csv';document.body.append(a);a.click();a.remove();URL.revokeObjectURL(url)}
csvBtn.disabled=true;printBtn.disabled=true;csvBtn.addEventListener('click',exportCSV);printBtn.addEventListener('click',()=>window.print())
}

initReports();

function initMobileNav(){let wrap=document.querySelector('.nav-more'),toggle=wrap?.querySelector('.nav-more-toggle');if(!wrap||!toggle)return;function close(){wrap.classList.remove('open');toggle.setAttribute('aria-expanded','false')}toggle.addEventListener('click',()=>{let open=!wrap.classList.contains('open');wrap.classList.toggle('open',open);toggle.setAttribute('aria-expanded',open?'true':'false')});document.addEventListener('click',e=>{if(!wrap.contains(e.target))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){close();toggle.focus()}})}
initMobileNav();
